  while (pos < input.length && input.charCodeAt(pos) <= 32) pos++;
  let value = 0;
  while (pos < input.length) {
    const c = input.charCodeAt(pos);
    if (c < 48 || c > 57) break;
    value = value * 10 + c - 48;
    pos++;
  }
  return value;
}

const n = nextInt();
const xs = new Int32Array(n);
for (let i = 0; i < n; i++) xs[i] = nextInt();

const a = new Int32Array(n);
const b = new Int32Array(n);
for (let i = 0; i < n; i++) {
  const y = nextInt();
  a[i] = xs[i] + y;
  b[i] = xs[i] - y;
}

let orderTemp = Array.from({ length: n }, (_, i) => i);
orderTemp.sort((i, j) => a[i] - a[j]);
const orderA = Int32Array.from(orderTemp);
orderTemp = null;

