function find(parent, x) {
  let root = x;
  while (parent[root] !== root) root = parent[root];

  while (parent[x] !== x) {
    const next = parent[x];
    parent[x] = root;
    x = next;
  }
  return root;
}

function fillBounds(order, values, distance, bounds) {
  let lo = 0;
  let hi = 0;

  for (let k = 0; k < n; k++) {
    const center = values[order[k]];

    while (lo < n && values[order[lo]] < center - distance) lo++;
    while (hi < n && values[order[hi]] <= center + distance) hi++;

    bounds[k] = lo;
    bounds[n + k] = hi;
  }
}

