  const boundsA = new Int32Array(2 * n);
  const boundsB = new Int32Array(2 * n);
  fillBounds(orderA, a, distance, boundsA);
  fillBounds(orderB, b, distance, boundsB);

  const nextA = new Int32Array(n + 1);
  const nextB = new Int32Array(n + 1);
  for (let i = 0; i <= n; i++) {
    nextA[i] = i;
    nextB[i] = i;
  }

  const color = new Int8Array(n);
  color.fill(-1);
  const queue = new Int32Array(n);

  const minA = [Infinity, Infinity];
  const maxA = [-Infinity, -Infinity];
  const minB = [Infinity, Infinity];
  const maxB = [-Infinity, -Infinity];

