      const bv = b[index];

      if (av < minA[newColor]) minA[newColor] = av;
      if (av > maxA[newColor]) maxA[newColor] = av;
      if (bv < minB[newColor]) minB[newColor] = bv;
      if (bv > maxB[newColor]) maxB[newColor] = bv;

      queue[tail++] = index;
      p = find(parent, p);
    }

    return tail;
  }

  for (let root = 0; root < n; root++) {
    if (color[root] !== -1) continue;

    color[root] = 0;
    minA[0] = maxA[0] = a[root];
    minB[0] = maxB[0] = b[root];

    let head = 0;
    let tail = 0;
    queue[tail++] = root;

    while (head < tail) {
      const u = queue[head++];
      const c = color[u];
      const av = a[u];
      const bv = b[u];

      if (
        minA[c] < av - distance ||
        maxA[c] > av + distance ||
        minB[c] < bv - distance ||
        maxB[c] > bv + distance
      ) {
        return false;
      }

      const opposite = 1 - c;
      const ra = rankA[u];
      const rb = rankB[u];

      tail = assignRange(orderA, nextA, nextB, rankB, 0, boundsA[ra], opposite, tail);
      tail = assignRange(orderA, nextA, nextB, rankB, boundsA[n + ra], n, opposite, tail);
      tail = assignRange(orderB, nextB, nextA, rankA, 0, boundsB[rb], opposite, tail);
      tail = assignRange(orderB, nextB, nextA, rankA, boundsB[n + rb], n, opposite, tail);
    }
  }

  return true;
}

let minA = a[0], maxA = a[0];
let minB = b[0], maxB = b[0];
for (let i = 1; i < n; i++) {
  if (a[i] < minA) minA = a[i];
  if (a[i] > maxA) maxA = a[i];
  if (b[i] < minB) minB = b[i];
  if (b[i] > maxB) maxB = b[i];
}

let low = 0;
let high = Math.max(maxA - minA, maxB - minB);

while (low < high) {
  const mid = Math.floor((low + high) / 2);
  if (feasible(mid)) high = mid;
  else low = mid + 1;
}

